CREATE OR REPLACE FUNCTION public.teacher_owns_class(_class_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(auth.uid(), 'ucitel'::public.app_role) AND EXISTS (SELECT 1 FROM public.classes c WHERE c.id = _class_id AND c.teacher_id = auth.uid() AND c.school_id = public.current_user_school_id()); $$;
REVOKE ALL ON FUNCTION public.teacher_owns_class(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.teacher_owns_class(uuid) TO authenticated, service_role;
ALTER POLICY "Triedy: škola vidí svoje" ON public.classes USING ((school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role)) OR public.teacher_owns_class(id));
ALTER POLICY "Triedy: škola vkladá svoje" ON public.classes WITH CHECK (school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role));
ALTER POLICY "Triedy: škola upravuje svoje" ON public.classes USING (school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role)) WITH CHECK (school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role));
ALTER POLICY "Triedy: škola maže svoje" ON public.classes USING (school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role));
ALTER POLICY "Žiaci: škola vidí svojich" ON public.students USING ((school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role)) OR public.teacher_owns_class(class_id));
ALTER POLICY "Žiaci: škola vkladá svojich" ON public.students WITH CHECK ((school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role)) OR (school_id = public.current_user_school_id() AND public.teacher_owns_class(class_id)));
ALTER POLICY "Žiaci: škola upravuje svojich" ON public.students USING (school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role)) WITH CHECK (school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role));
ALTER POLICY "Žiaci: škola maže svojich" ON public.students USING (school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role));
ALTER POLICY "Pokusy: škola vidí svoje" ON public.test_attempts USING ((school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role)) OR public.teacher_owns_class(class_id));
ALTER POLICY "Odpovede: škola vidí svoje cez pokus" ON public.test_answers USING (EXISTS (SELECT 1 FROM public.test_attempts a WHERE a.id = test_answers.attempt_id AND ((a.school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role)) OR public.teacher_owns_class(a.class_id))));
ALTER POLICY "Priradenia: škola vidí svoje" ON public.test_assignments USING (scope = 'all' OR (school_id = public.current_user_school_id() AND public.has_role(auth.uid(), 'skola'::public.app_role)) OR public.teacher_owns_class(class_id));
CREATE POLICY "Teachers assign published tests to own classes" ON public.test_assignments FOR INSERT TO authenticated WITH CHECK (scope = 'class' AND school_id = public.current_user_school_id() AND public.teacher_owns_class(class_id) AND created_by = auth.uid() AND EXISTS (SELECT 1 FROM public.tests t WHERE t.id = test_assignments.test_id AND t.status = 'published'));
CREATE POLICY "Teachers update own assignments" ON public.test_assignments FOR UPDATE TO authenticated USING (created_by = auth.uid() AND scope = 'class' AND public.teacher_owns_class(class_id)) WITH CHECK (created_by = auth.uid() AND scope = 'class' AND school_id = public.current_user_school_id() AND public.teacher_owns_class(class_id));
CREATE OR REPLACE FUNCTION public.protect_profile_school_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(), 'admin'::public.app_role) AND NOT public.has_role(auth.uid(), 'koordinator'::public.app_role) THEN IF TG_OP = 'INSERT' THEN IF NEW.school_id IS NOT NULL THEN RAISE EXCEPTION 'School assignment is managed by coordinators'; END IF; ELSIF NEW.school_id IS DISTINCT FROM OLD.school_id THEN RAISE EXCEPTION 'School assignment is managed by coordinators'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_profile_school_assignment BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_school_assignment();